-- Forecast the parts mix for problem P02, every region, next 12 weeks.
-- Target: rolling 4-week attach rate per candidate part (share of jobs using it).
-- Covariates known ahead: forecast temperature, install-base units at risk.
-- Generated by bigquery/make_sql.py.

WITH weekly AS (
  SELECT
    j.week, j.region, j.jobs,
    SUM(IF(u.part_id = 'IGN-HSI', u.uses, 0)) AS ign_hsi,
    SUM(IF(u.part_id = 'FS-01', u.uses, 0)) AS fs_01,
    SUM(IF(u.part_id = 'IND-MTR', u.uses, 0)) AS ind_mtr,
    SUM(IF(u.part_id = 'PS-0.55', u.uses, 0)) AS ps_0_55,
    SUM(IF(u.part_id = 'CB-50A', u.uses, 0)) AS cb_50a,
    SUM(IF(u.part_id = 'GV-24V', u.uses, 0)) AS gv_24v
  FROM trunk.jobs_weekly AS j
  LEFT JOIN trunk.part_usage_weekly AS u
    USING (week, region, problem_code)
  WHERE j.problem_code = 'P02'
  GROUP BY j.week, j.region, j.jobs
),
rolling AS (
  SELECT
    week, region,
    SAFE_DIVIDE(SUM(ign_hsi) OVER w, SUM(jobs) OVER w) AS ign_hsi,
    SAFE_DIVIDE(SUM(fs_01) OVER w, SUM(jobs) OVER w) AS fs_01,
    SAFE_DIVIDE(SUM(ind_mtr) OVER w, SUM(jobs) OVER w) AS ind_mtr,
    SAFE_DIVIDE(SUM(ps_0_55) OVER w, SUM(jobs) OVER w) AS ps_0_55,
    SAFE_DIVIDE(SUM(cb_50a) OVER w, SUM(jobs) OVER w) AS cb_50a,
    SAFE_DIVIDE(SUM(gv_24v) OVER w, SUM(jobs) OVER w) AS gv_24v
  FROM weekly
  WINDOW w AS (PARTITION BY region ORDER BY week ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)
),
-- History rows carry the targets; the 12 future rows carry NULL targets and
-- the covariates, which is how AI.FORECAST knows the horizon's conditions.
data AS (
  SELECT
    wx.week, wx.region,
    r.ign_hsi, r.fs_01, r.ind_mtr, r.ps_0_55, r.cb_50a, r.gv_24v,
    wx.avg_temp_f,
    ib.units_at_risk
  FROM trunk.weather_weekly AS wx
  JOIN trunk.install_base_weekly AS ib
    ON ib.week = wx.week AND ib.region = wx.region AND ib.problem_code = 'P02'
  LEFT JOIN rolling AS r
    ON r.week = wx.week AND r.region = wx.region
)
SELECT *
FROM AI.FORECAST(
  TABLE data,
  model => 'TimesFM 3.0',
  timestamp_col => 'week',
  id_cols => ['region'],
  target_cols => ['ign_hsi', 'fs_01', 'ind_mtr', 'ps_0_55', 'cb_50a', 'gv_24v'],
  future_covariate_cols => ['avg_temp_f', 'units_at_risk'],
  horizon => 12,
  confidence_level => 0.8       -- 80% interval: the 10th and 90th percentiles
);
